<style>
	section {
		container-type: size;
		container-name: fullscreen-header;

		background-color: #efcdcc;
		background-size: cover;
		background-position: top;
		background-repeat: no-repeat;
		min-height: 100vh;
		width: 100%;
		display: flex;
		align-items: center;
		justify-content: center;
		text-align: center;
		overflow: hidden;
		position: relative;
	}

	section::before {
		content: '';
		position: absolute;
		inset: 0;
		background: rgba(0, 0, 0, 0.45);
		z-index: 0;
	}

	span {
		z-index: 1;
		text-transform: uppercase;
		color: #6b0d0d;
	}

	.word-1 {
		position: absolute;
		top: 30%;
		left: 80px;
		rotate: -45deg;
	}
	.word-2 {
		position: absolute;
		bottom: 380px;
		right: 30%;
		rotate: -45deg;
	}
	.word-3 {
		position: absolute;
		bottom: 30%;
		left: 30%;
		rotate: -45deg;
	}
	.svg-overlay-1 svg {
		position: absolute;
		width: 150px;
		height: 150px;
		top: 45px;
		left: 75px;
		rotate: -90deg;
		scale: 2;
	}

	.svg-overlay-2 svg {
		position: absolute;
		width: 150px;
		height: 150px;
		bottom: 100px;
		right: 140px;
		rotate: 90deg;
		scale: 2.8;
	}
	.svg-overlay-3 svg {
		position: absolute;
		bottom: 230px;
		left: 20px;
		rotate: 45deg;
	}
	.svg-overlay-4 svg {
		position: absolute;
		top: 70px;
		right: 20px;
	}
	.svg-overlay-5 svg {
		display: none;
	}
	.svg-overlay-6 svg {
		display: none;
	}
	/* Tablet */
	@container fullscreen-header (min-width: 710px) {
		.word-1 {
			top: 20%;
			left: 300px;
			rotate: 0deg;
		}
		.word-2 {
			bottom: 50%;
			left: 30%;
			rotate: 0deg;
		}
		.word-3 {
			bottom: 30%;
			left: 30%;
			rotate: 0deg;
		}
	}

	/* Desktop */
	@container fullscreen-header (min-width: 1024px) {
		.svg-overlay-1 svg {
			position: absolute;
			top: 10%;
			left: 88%;
			rotate: 0deg;
			scale: 3;
		}
		.svg-overlay-2 svg {
			bottom: 20%;
			right: 0;
			left: 6%;
			scale: 3.5;
			rotate: 180deg;
		}
		.svg-overlay-3 svg {
			position: absolute;
			top: -5%;
			bottom: 230px;
			left: 60%;
			rotate: 0deg;
		}
		.svg-overlay-4 svg {
			position: absolute;
			top: 75%;
			right: 0;
			left: 30%;
		}
		.svg-overlay-5 svg {
			position: absolute;
			display: block;
            bottom: 0;
            right: 20%;
		}
		.svg-overlay-6 svg {
			position: absolute;
			display: block;
            top: 0;
            left: 0;

		}
		.word-1 {
			top: 20%;
